const BY_ID = new Map(REFRIGERANTS.map((r) => [r.id, r]));
export function refrigerant(id: string): Refrigerant | undefined {
  return BY_ID.get(id);
}

export function isFlammable(id: string): boolean {
  const s = BY_ID.get(id)?.safety;
  return s === 'A2L' || s === 'A2' || s === 'A3' || s === 'B2L';
}

/** The safety reminder for a refrigerant's class (null for A1). The standard named comes from the country profile. */
export function safetyNote(id: string, standard: string): string | null {
  const s = BY_ID.get(id)?.safety;
  if (s === 'A2L') {
    return `Mildly flammable (A2L): no ignition sources, ventilate, use A2L-rated tools. Charge and room-size limits: ${standard} and the unit's manual.`;
  }
  if (s === 'A3' || s === 'A2') {
    return `Highly flammable (${s}): hydrocarbon-trained only, gas detector on, no ignition sources, never braze a charged system. Charge limits: ${standard} and the manufacturer's data.`;
  }
  if (s === 'B2L') {
    return 'B2L: toxic and mildly flammable. Ammonia systems are specialist work: follow site procedures, use detection and the right PPE.';
  }
  return null;
}

export const SAFETY_LABEL: Record<SafetyClass, string> = {
  A1: 'A1 · non-flammable',
  A2L: 'A2L · mildly flammable',
  A2: 'A2 · flammable',
  A3: 'A3 · highly flammable',
  B2L: 'B2L · toxic, mildly flammable',
};
